export function migrationReport(manifest) {
  const { sections, models } = manifest;
  const completed = sections.filter(section => section.complete);
  const lines = [
    '# Catalog 3D asset migration', '',
    'Generated by the furniture authoring pipeline. This tracks standalone GLB asset',
    'coverage. The game now consumes the 179 furniture/prop GLBs; customized',
    'people and pets retain their SVG rigs. See [live integration](ROOM_MODEL_INTEGRATION.md). Sections follow',
    'the actual catalog order. A section is reviewed as a family before proceeding.', '',
    `Sections with complete export coverage: **${completed.map(section => section.label).join(', ') || 'None'}**.`, '',
    '| Order | Catalog section | Exported | Total | Status |',
    '| --- | --- | ---: | ---: | --- |',
    ...sections.map(section => `| ${section.order} | ${section.label} | ${section.exported.length} | ${section.total} | ${section.complete ? 'Export coverage complete' : section.exported.length ? 'In progress' : 'Pending'} |`),
    '', '## Sections with full asset coverage', '',
  ];
  for (const section of completed) {
    lines.push(`### ${section.label}`, '', '| Asset | Catalog key | Triangles | GLB bytes |', '| --- | --- | ---: | ---: |');
    for (const key of section.exported) {
      const model = models[key];
      lines.push(`| [${model.label}](../prototypes/furniture/assets/${key}.glb) | ${key} | ${model.triangles.toLocaleString('en-US')} | ${model.bytes.toLocaleString('en-US')} |`);
    }
    lines.push('');
  }
  lines.push(`The next section to author is **${sections.find(section => !section.complete)?.label || 'none'}**.`,
    'See [the documented approach](CATALOG_3D_APPROACH.md), [the workshop guide](../prototypes/furniture/README.md) and',
    '[the verification report](ROOM_MODEL_INTEGRATION.md). Living entries include',
    'starter articulated Idle/Walk clips. Production wardrobe/body customization,',
    'growth and all-angle 3D actor integration remain future work. Current game',
    'furniture contact uses the preserved SVG actors and GLB-backed props.', '');
  return lines.join('\n');
}
